<script setup lang="ts">
import { Head, Link, usePage } from '@inertiajs/vue3';
import AppLayout from '../../layouts/AppLayout.vue';
import ReadyInvoice from '../../components/ReadyInvoice.vue';
import { money, type Snapshot } from '../../types/salesOrder';
defineProps<Omit<Snapshot, 'perlakuan_ppn'> & { calc: Record<string, string>; closed: boolean; canManage: boolean; canInvoice: boolean; pendingReconfirmation: boolean; exited: {id:number;nama:string;keluar_jenis:string;keluar_alasan:string}[]; revisions: {revisi:number;created_date:string}[]; invoice: { id: number; nomor: string } | null; documents: { id: number; nama_file: string; ukuran_byte: number; created_date: string; nm_lengkap: string }[]; companyConfirmation: { id: number; surat_konfirmasi_nama: string } | null }>();
const page = usePage();
const allowed = (menu: string) => ((page.props.permissions as Record<string, string[]>)?.[menu] || []).includes('View');
</script>
<template>
    <Head :title="so.nomor" /><AppLayout title="Sales Order"><Link :href="`/sales-order/program/${program.id}`">← Sales Order program</Link><h1>{{ so.nomor }}</h1><p class="notice">{{ so.status_tampil }}{{ closed ? ' · Program Closed' : '' }}</p><p v-for="e in $page.props.errors" :key="String(e)" class="error" role="alert">{{ e }}</p>
        <div class="row-actions"><ReadyInvoice v-if="canManage && so.status === 'open'" :so="so" :kepada="quotation.kepada_nama" :count="peserta.length" :total="calc.grand_total!" /><a :href="`/sales-order/${so.id}/pdf`" target="_blank" rel="noopener">Print Out SO</a><Link v-if="allowed('quotation_program')" :href="`/quotation/${quotation.id}`">Buka quotation</Link></div>
        <section class="panel"><h2>Data Sales Order</h2><p>Tanggal tersimpan: {{ so.tanggal }} · Quotation: {{ quotation.nomor }} · Sales: {{ sales }}</p><p>Penjualan Program: {{ program.nomor }} · {{ program.jenis.toUpperCase() }}</p><p v-if="so.siap_date">Siap invoice oleh {{ so.siap_nama }} · {{ so.siap_date }}</p></section>
        <section class="panel"><h2>Ditujukan Kepada</h2><p>{{ quotation.tujuan }} · {{ quotation.kepada_nama }} · u.p. {{ quotation.up_nama }}</p><p>{{ quotation.alamat }}</p><p v-if="company">Perlakuan PPN: {{ company.perlakuan_ppn || 'Belum dilengkapi' }}</p></section>
        <section class="panel"><h2>Program</h2><p v-for="k in produk" :key="k.nomor">{{ k.nomor }} · {{ k.judul }} · {{ k.varian }} · {{ k.sertifikat }}</p><p>{{ program.tgl_mulai }} s.d. {{ program.tgl_selesai }} · {{ program.waktu }} · {{ program.lokasi }}</p><p>{{ program.durasi_hari }} hari · {{ program.jam_pembelajaran }} JP · {{ quotation.skema_harga === 'allin' ? 'All-in 1 company' : 'Per peserta' }}</p></section>
        <section class="panel"><h2>Harga peserta Deal</h2><p v-if="quotation.skema_harga === 'allin'">Harga all-in {{ money(quotation.harga_allin) }} · tambahan {{ calc.n_tambahan }} peserta: {{ money(calc.tambahan) }}</p><dl><template v-for="(label, key) in { subtotal: 'Subtotal', diskon: 'Diskon', dpp: 'Setelah diskon', ppn: 'PPN', biaya_lain: 'Biaya Lain-lain', grand_total: 'Total Sales Order' }" :key="key"><dt>{{ label }}</dt><dd>{{ money(calc[key]) }}</dd></template></dl></section>
        <section class="panel"><h2>Dokumen Deal</h2><p>{{ quotation.dokumen_keterangan }}</p><ul><li v-for="d in documents" :key="d.id"><a :href="`/sales-order/${so.id}/documents/quotation/${d.id}?preview=1`" target="_blank" rel="noopener">{{ d.nama_file }}</a> · {{ Math.ceil(d.ukuran_byte / 1024) }} KB · {{ d.nm_lengkap }} · {{ d.created_date }} <a :href="`/sales-order/${so.id}/documents/quotation/${d.id}`">Unduh</a></li></ul></section>
        <section class="panel"><h2>Peserta Deal &amp; Surat Konfirmasi</h2><a :href="`/sales-order/${so.id}/letters`" target="_blank" rel="noopener">Confirmation Letter (semua peserta Deal)</a><div class="table-wrap"><table><caption class="sr-only">Peserta Deal</caption><thead><tr><th>Nama</th><th>Jabatan / Instansi</th><th>Kontak</th><th>Masuk lewat</th><th>Surat Konfirmasi</th></tr></thead><tbody><tr v-for="p in peserta" :key="p.id"><td>{{ p.nama }}</td><td>{{ p.jabatan }}<small>{{ p.instansi }}</small></td><td>{{ p.email }}<small>{{ p.no_wa || p.no_hp }}</small></td><td>{{ program.jenis === 'b2b' ? 'Daftar PIC' : p.sumber }}<small>{{ p.tgl_isi }}</small></td><td><template v-if="program.jenis === 'b2b' && companyConfirmation"><a :href="`/sales-order/${so.id}/documents/company-confirmation/${companyConfirmation.id}?preview=1`" target="_blank" rel="noopener">Lihat surat Company</a> · <a :href="`/sales-order/${so.id}/documents/company-confirmation/${companyConfirmation.id}`">Unduh</a></template><template v-else-if="p.surat_konfirmasi"><a :href="`/sales-order/${so.id}/documents/confirmation/${p.id}?preview=1`" target="_blank" rel="noopener">Lihat</a> · <a :href="`/sales-order/${so.id}/documents/confirmation/${p.id}`">Unduh</a></template><span v-else>Belum tersedia</span></td></tr></tbody></table></div></section>
        <section v-if="exited.length" class="panel"><h2>Peserta Keluar</h2><p v-for="p in exited" :key="p.id">{{ p.nama }}: {{ p.keluar_jenis }}. {{ p.keluar_alasan }}</p></section><section v-if="revisions.length" class="panel"><h2>Riwayat revisi Sales Order</h2><p v-for="r in revisions" :key="r.revisi"><a :href="`/quotation/${quotation.id}/revisi/${r.revisi}/so`" target="_blank" rel="noopener">Versi {{ r.revisi || 'awal' }}</a> {{ r.created_date }}</p></section><section class="panel"><h2>Invoice</h2><template v-if="invoice"><Link v-if="allowed('invoicing')" :href="`/invoicing/${invoice.id}`">{{ invoice.nomor }}</Link><p v-else>{{ invoice.nomor }}</p></template><Link v-else-if="canInvoice && !pendingReconfirmation && peserta.length && so.status === 'siap'" :href="`/invoicing/create?id_sales_order=${so.id}`">Buat Invoice</Link><p v-else-if="pendingReconfirmation">Menunggu seluruh konfirmasi ulang peserta Deal tuntas.</p><p v-else>{{ so.status === 'siap' ? 'Menunggu pembuatan Invoice.' : 'Invoice menunggu status Siap invoice.' }}</p></section>
    </AppLayout>
</template>
